CREATE TABLE users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(5) NOT NULL DEFAULT 'USER' CHECK(role IN ('USER','ADMIN')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE tlds(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,extension VARCHAR(20) NOT NULL UNIQUE,registration_price NUMERIC(10,2) NOT NULL CHECK(registration_price>=0),renewal_price NUMERIC(10,2) NOT NULL CHECK(renewal_price>=0),active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE domains(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(63) NOT NULL,extension VARCHAR(20) NOT NULL REFERENCES tlds(extension),owner_id BIGINT NOT NULL REFERENCES users(id),expires_at DATE NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(name,extension)); CREATE INDEX idx_domains_owner ON domains(owner_id); CREATE INDEX idx_domains_expiry ON domains(expires_at);
CREATE TABLE orders(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),domain_id BIGINT REFERENCES domains(id),order_type VARCHAR(20) NOT NULL CHECK(order_type IN ('REGISTRATION','RENEWAL','TRANSFER_PURCHASE')),amount NUMERIC(10,2) NOT NULL,status VARCHAR(10) NOT NULL CHECK(status IN ('COMPLETED','FAILED')),request_key VARCHAR(100) UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX idx_orders_user ON orders(user_id,created_at); CREATE INDEX idx_orders_key ON orders(request_key);
CREATE TABLE payments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id BIGINT NOT NULL UNIQUE REFERENCES orders(id),amount NUMERIC(10,2) NOT NULL,status VARCHAR(10) NOT NULL CHECK(status IN ('SUCCESS','FAILED')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX idx_pay_status ON payments(status);
CREATE TABLE dns_records(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,domain_id BIGINT NOT NULL REFERENCES domains(id) ON DELETE CASCADE,record_type VARCHAR(5) NOT NULL CHECK(record_type IN ('A','AAAA','CNAME','MX','TXT','NS')),name VARCHAR(253) NOT NULL,value VARCHAR(1000) NOT NULL,priority INT,ttl INT NOT NULL DEFAULT 3600); CREATE INDEX idx_dns_domain ON dns_records(domain_id);
CREATE TABLE transfers(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,domain_id BIGINT NOT NULL REFERENCES domains(id),sender_id BIGINT NOT NULL REFERENCES users(id),receiver_id BIGINT NOT NULL REFERENCES users(id),status VARCHAR(10) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','ACCEPTED','REJECTED')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX idx_transfer_party ON transfers(sender_id,receiver_id,status); CREATE INDEX idx_transfer_receiver ON transfers(receiver_id,status);
CREATE TABLE auctions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,domain_id BIGINT NOT NULL REFERENCES domains(id),seller_id BIGINT NOT NULL REFERENCES users(id),starting_price NUMERIC(10,2) NOT NULL,min_increment NUMERIC(10,2) NOT NULL,starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,status VARCHAR(10) NOT NULL DEFAULT 'LIVE' CHECK(status IN ('LIVE','CLOSED','UNSOLD')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX idx_auction_live ON auctions(status,ends_at);
CREATE TABLE bids(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,auction_id BIGINT NOT NULL REFERENCES auctions(id),bidder_id BIGINT NOT NULL REFERENCES users(id),amount NUMERIC(10,2) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX idx_bid_high ON bids(auction_id,amount);
